    zwp_linux_dmabuf_feedback_v1::~zwp_linux_dmabuf_feedback_v1()
    {
        for (auto resource : std::as_const(m_resource_map))
            resource->zwp_linux_dmabuf_feedback_v1_object = nullptr;

        if (m_resource)
            m_resource->zwp_linux_dmabuf_feedback_v1_object = nullptr;

        if (m_global) {
            if (m_globalRemovedEvent)
                wl_event_source_remove(m_globalRemovedEvent);
            wl_global_destroy(m_global);
            wl_list_remove(&m_displayDestroyedListener.link);
        }
    }

