    void zwp_linux_dmabuf_feedback_v1::init(struct ::wl_display *display, int version)
    {
        m_display = display;
        m_global = wl_global_create(display, &::zwp_linux_dmabuf_feedback_v1_interface, version, this, bind_func);
        m_displayDestroyedListener.notify = zwp_linux_dmabuf_feedback_v1::display_destroy_func;
        m_displayDestroyedListener.parent = this;
#ifdef HAVE_ACK_GLOBAL_REMOVE
        wl_global_set_withdrawn_listener(m_global, [](wl_global *global) {
            auto object = static_cast<zwp_linux_dmabuf_feedback_v1 *>(wl_global_get_user_data(global));
            object->zwp_linux_dmabuf_feedback_v1_destroy_global();
        });
#endif
        wl_display_add_destroy_listener(display, &m_displayDestroyedListener);
    }

